svg.script:
(function () {
  var root = document.documentElement;
  var NS = 'http://www.w3.org/2000/svg';
  var hc = document.getElementById('posterHoverCard');
  var W = 1280, H = 5209;
  var activeEp = '';
  var hideT = null;

  function wrapTxt(str, maxC) {
    var words = String(str || '').split(/\s+/).filter(Boolean);
    if (!words.length) return [''];
    var lines = [], cur = words[0];
    for (var i = 1; i < words.length; i++) {
      if (cur.length + 1 + words[i].length <= maxC) cur += ' ' + words[i];
      else { lines.push(cur); cur = words[i]; }
    }
    lines.push(cur);
    return lines;
  }

  function setEp(ep) {
    if (ep === activeEp) return;
    if (activeEp) {
      root.querySelectorAll('[data-epoch="' + activeEp + '"]').forEach(function (n) { n.classList.remove('is-hov'); });
    }
    activeEp = ep || '';
    if (activeEp) {
      root.querySelectorAll('[data-epoch="' + activeEp + '"]').forEach(function (n) { n.classList.add('is-hov'); });
    }
  }

  function showHoverCard(linkEl) {
    if (!hc || !linkEl) return;
    clearTimeout(hideT);
    var ep = linkEl.getAttribute('data-epoch') || '';
    setEp(ep);
    var stopNum = linkEl.getAttribute('data-stop') || '';
    var total = linkEl.getAttribute('data-total') || '68';
    var act = linkEl.getAttribute('data-act') || '';
    var acol = linkEl.getAttribute('data-acol') || '#7a4cf2';
    var who = linkEl.getAttribute('data-who') || '';
    var tax = linkEl.getAttribute('data-tax') || '';
    var when = linkEl.getAttribute('data-when') || '';
    var hook = linkEl.getAttribute('data-hook') || '';
    var href = linkEl.getAttribute('href') || '#';
    var mx = parseFloat(linkEl.getAttribute('data-mx') || '640');
    var my = parseFloat(linkEl.getAttribute('data-my') || '400');

    var cw = 308;
    var descLines = wrapTxt(hook, 42);
    var hasTax = Boolean(tax);
    var descStartY = hasTax ? 64 : 50;
    var btnY = descStartY + descLines.length * 16 + 8;
    var ch = btnY + 40;

    var cx = mx < W * 0.5 ? Math.min(W - cw - 16, mx + 28) : Math.max(16, mx - cw - 28);
    var cy = Math.max(16, Math.min(H - ch - 16, my - ch * 0.42));

    while (hc.firstChild) hc.removeChild(hc.firstChild);
    hc.setAttribute('transform', 'translate(' + cx.toFixed(1) + ',' + cy.toFixed(1) + ')');
    hc.setAttribute('display', 'inline');

    var bridge = document.createElementNS(NS, 'rect');
    bridge.setAttribute('x', '-18'); bridge.setAttribute('y', '-14');
    bridge.setAttribute('width', String(cw + 36)); bridge.setAttribute('height', String(ch + 28));
    bridge.setAttribute('fill', '#ffffff'); bridge.setAttribute('fill-opacity', '0');
    hc.appendChild(bridge);

    var bg = document.createElementNS(NS, 'rect');
    bg.setAttribute('x', '0'); bg.setAttribute('y', '0');
    bg.setAttribute('width', String(cw)); bg.setAttribute('height', String(ch));
    bg.setAttribute('rx', '10'); bg.setAttribute('fill', '#ffffff');
    bg.setAttribute('stroke', '#cbd1e1'); bg.setAttribute('stroke-width', '1.3');
    bg.setAttribute('filter', 'url(#popShadow)');
    hc.appendChild(bg);

    var bar = document.createElementNS(NS, 'rect');
    bar.setAttribute('x', '0'); bar.setAttribute('y', '0');
    bar.setAttribute('width', String(cw)); bar.setAttribute('height', '4');
    bar.setAttribute('rx', '2'); bar.setAttribute('fill', acol);
    hc.appendChild(bar);

    var ey = document.createElementNS(NS, 'text');
    ey.setAttribute('x', '14'); ey.setAttribute('y', '21');
    ey.setAttribute('class', 'hc-eyebrow');
    ey.textContent = 'Stop ' + stopNum + ' of ' + total + ' · Act ' + act + ' · ' + when;
    hc.appendChild(ey);

    var wt = document.createElementNS(NS, 'text');
    wt.setAttribute('x', '14'); wt.setAttribute('y', '40');
    wt.setAttribute('class', 'hc-who');
    wt.textContent = who;
    hc.appendChild(wt);

    if (hasTax) {
      var tt = document.createElementNS(NS, 'text');
      tt.setAttribute('x', '14'); tt.setAttribute('y', '55');
      tt.setAttribute('class', 'hc-tax');
      tt.textContent = tax;
      hc.appendChild(tt);
    }

    descLines.forEach(function (ln, idx) {
      var dt = document.createElementNS(NS, 'text');
      dt.setAttribute('x', '14');
      dt.setAttribute('y', String(descStartY + 11 + idx * 16));
      dt.setAttribute('class', 'hc-desc');
      dt.textContent = ln;
      hc.appendChild(dt);
    });

    var a = document.createElementNS(NS, 'a');
    a.setAttribute('href', href);
    a.setAttribute('target', '_top');
    a.setAttribute('class', 'poster-link hc-btn');
    var btnLabel = 'Open Stop ' + stopNum + ': ' + (who.length > 22 ? who.slice(0, 21) + '…' : who) + ' →';
    var btnW = Math.min(cw - 28, Math.max(154, btnLabel.length * 6.7 + 26));
    var br = document.createElementNS(NS, 'rect');
    br.setAttribute('x', '14'); br.setAttribute('y', String(btnY));
    br.setAttribute('width', String(btnW.toFixed(0))); br.setAttribute('height', '28');
    br.setAttribute('rx', '6'); br.setAttribute('class', 'hc-btn-bg');
    a.appendChild(br);

    var bt = document.createElementNS(NS, 'text');
    bt.setAttribute('x', '26'); bt.setAttribute('y', String(btnY + 18));
    bt.setAttribute('class', 'hc-btn-txt');
    bt.textContent = btnLabel;
    a.appendChild(bt);
    hc.appendChild(a);
  }

  function scheduleHide() {
    clearTimeout(hideT);
    hideT = setTimeout(function () {
      if (hc) hc.setAttribute('display', 'none');
      setEp('');
    }, 220);
  }

  root.addEventListener('pointerover', function (ev) {
    var medLink = ev.target && ev.target.closest ? ev.target.closest('a.step-med-link') : null;
    if (medLink) {
      showHoverCard(medLink);
      return;
    }
    if (ev.target && ev.target.closest && ev.target.closest('#posterHoverCard')) {
      clearTimeout(hideT);
      return;
    }
    var epEl = ev.target && ev.target.closest ? ev.target.closest('[data-epoch]') : null;
    if (epEl) {
      clearTimeout(hideT);
      setEp(epEl.getAttribute('data-epoch'));
    } else {
      scheduleHide();
    }
  });
  root.addEventListener('pointerleave', scheduleHide);
  root.addEventListener('focusin', function (ev) {
    var medLink = ev.target && ev.target.closest ? ev.target.closest('a.step-med-link') : null;
    if (medLink) showHoverCard(medLink);
  });
  root.addEventListener('keydown', function (ev) {
    if (ev.key === 'Escape' && hc) {
      clearTimeout(hideT);
      hc.setAttribute('display', 'none');
    }
  });
})();
